#pragma once
// What this build fetches from, generated by CMake.
#include <optional>
#include <string_view>

#include "crpp/assets/assets.hpp"

namespace crpp::assets {

// Signed with the update key (ADR 0008). Empty when the build has no key or no address,
// and then only a folder beside the exe or --asset-url provides the files.
[[nodiscard]] std::optional<Repository> official_repository();
// The name of its catalog for this exe's pack format (ADR 0009), which --asset-url serves too.
[[nodiscard]] std::string_view official_catalog_name();

}  // namespace crpp::assets
